def dinic(graph, source, sink):
    n = len(graph)
    level = [0] * n

    def bfs():
        for i in range(n):
            level[i] = -1
        level[source] = 0
        q = deque([source])

        while q:
            u = q.popleft()
            for v in range(n):
                if level[v] == -1 and graph[u][v] > 0:
                    level[v] = level[u] + 1
                    q.append(v)

        return level[sink] != -1

    def dfs(u, flow):
        if u == sink:
            return flow
        for v in range(n):
            if level[v] == level[u] + 1 and graph[u][v] > 0:
                pushed = dfs(v, min(flow, graph[u][v]))
                if pushed > 0:
                    graph[u][v] -= pushed
                    graph[v][u] += pushed
                    return pushed
        return 0

    max_flow = 0
    while bfs():
        while pushed := dfs(source, float('inf')):
            max_flow += pushed

    return max_flow  # O(V^2E)
